@push('scripts')<script>const box=document.getElementById('sections');let count=0;document.getElementById('addSection').onclick=()=>{if(count>=5)return;box.insertAdjacentHTML('beforeend',`<div class="border rounded-lg p-3 relative"><button type="button" class="absolute right-2 top-1 text-rose-500" onclick="this.parentElement.remove()">×</button><input name="sections[${count}][image]" type="file" accept="image/*" class="w-full mb-2"><input name="sections[${count}][title]" placeholder="Section title" class="w-full border rounded p-2 mb-2"><textarea name="sections[${count}][message]" placeholder="Section message" class="w-full border rounded p-2"></textarea><input name="sections[${count}][sort_order]" type="hidden" value="${count}"></div>`);count++}</script>@endpush
